"use strict";

import * as Modes from "approot/global/ui-components/tree/modes.js";

export class EditAnnouncementCtrl {
	/*@ngInject*/
	constructor($scope, pageContext, $q, $location, $appLoader, breadcrumbRouting, emAnnouncementsRepository, $routeParams, changeTracker, $alerts, $dialogs, modalSelectOrganizations) {
		this.language = language;
		this.$location = $location;
		this.$dialogs = $dialogs;

		this.$appLoader = $appLoader;
		this.breadcrumbRouting = breadcrumbRouting;
		this.emAnnouncementsRepository = emAnnouncementsRepository;
		this.changeTracker = changeTracker;
		this.$alerts = $alerts;
		this.modalSelectOrganizations = modalSelectOrganizations;

		this.selectAll = true;

		const announcementId = parseInt($routeParams.announcementId) || 0;
		this.state = {
			dataReady: false,
			createMode: !announcementId
		};

		pageContext.title = this.state.createMode ? this.language.Generic.Announcement.kTitleAnnounce : this.language.Generic.Announcement.kEditingAnnouncements
		pageContext.parent = {
			title: this.language.Generic.Announcement.kTitleViewAnn,
			href: `/`,
		}

		let data = {
			announcementId: announcementId,
			deleteDateStr: "",
			announcement: null,
			recipientGroups: []
		}

		this.descriptionMaxSize = 2000;
		this.data = data;

		const currentSizeMessage = () => {
			let currentSize = this.data.announcement && this.data.announcement.description && this.data.announcement.description.length || 0;
			this.currentSizeMessage = this.language.Generic.Announcement.kAnnouncementCurrentLengthMessage.replace("{0}", currentSize);
		}

		$scope.$watch(() => this.data.announcement && this.data.announcement.description, currentSizeMessage);

		this.tinymceOptions = {
			menubar: false,
			height: 300,
			paste_as_text: true,
			plugins: 'link image lists table colorpicker textcolor paste',
			toolbar: 'undo redo | bold italic | forecolor backcolor | alignleft aligncenter alignright | bullist numlist | link image',
			init_instance_callback: function (editor) {
				editor.on('Change', function (e) {
					changeTracker.dataWasChanged();
				});
			}
		}

		setTimeout(() => { dateInput.initDateInputs(new Date().addDays(1), new Date().addYears(1)) }, 200);

		const promises = [];

		const refsReady = this.emAnnouncementsRepository.getSchoolRoles()
			.then((roles) => {
				new RolesManager().beautify(roles);
				this.data.recipientGroups = roles;
			});

		promises.push(refsReady);
		promises.push(this.initAnnounce());

		$q.all(promises).then(() => {
			this.syncDate();
			this.initFileAttachments();

			this.state.dataReady = true;
			this.$appLoader.hide();
		});


		this.selectSchools = (selected) => {
			this.selected = selected;
			this.selected["updateMethod"] = this.selectSchools;
			this.selected["editModel"] = getEditModel();
			this.selected["count"] = 5;

			return selected;
		}

		this.selected = {
			updateMethod: this.selectSchools
		}

		this.schoolsTreeModel = {
			selected: this.selected && this.selected.selectedIds,
			functype: null,
			settings: {
				mode: Modes.multi,
				order: null // Levels.province
			}
		}
	};

	initFileAttachments() {

		const files = this.data.announcement.attachments || [];

		this.fa = {
			options: {
				multiple: true,
				showDescription: true
			},
			data: {
				files: files,
				context: {
					announcementId: this.data.announcementId
				}
			}
		}
	}

	initAnnounce() {
		if (this.data.announcementId) {
			const announceLoad = this.emAnnouncementsRepository.getEdit(this.data.announcementId)
				.then((announcement) => {
					this.data.announcement = announcement;
					if (announcement.recipientGroup.length === 1 && announcement.recipientGroup[0] === 0) {
						refsReady.then(() => {
							announcement.recipientGroup = _.map(this.data.recipientGroups, (g) => g.id);
						});
					}
					this.selected = {
						selectedIds: announcement.schoolIds
					}
					return this.data.announcement;
				})
				.catch(() => this.breadcrumbRouting.back());

			return announceLoad;
		} else {
			this.data.announcement = {
				deleteDate: new Date().addDays(10),
				recipientGroup: [],
				title: "",
				description: ""
			};

			this.selected = {
				selectedIds: []
			}

			return Promise.resolve(this.data.announcement);
		}
	}

	syncDate(){
		this.data.deleteDateStr = date2str(new Date(this.data.announcement.deleteDate));
	}

	toggleRecipientGroup(groupId){
		if (groupId === -1) {
			if (this.data.announcement.recipientGroup.length === this.data.recipientGroups.length) {
				this.data.announcement.recipientGroup = [];
			} else {
				this.data.announcement.recipientGroup = this.data.recipientGroups.map(x => x.id);
			}
		} else {
			var idx = this.data.announcement.recipientGroup.indexOf(groupId);
			if (idx > -1) {
				this.data.announcement.recipientGroup.splice(idx, 1);
			}
			else {
				this.data.announcement.recipientGroup.push(groupId);
			}
		}
	}

	getEditModel() {
		return {
			mode: Modes.multi | Modes.edit,
			functype: null, //currentmodel.functype,
			selected: this.selected.selectedIds || [],
			//order: currentmodel.settings.order
		}
	}

	openChooseDialogForSchools() {
		let model = this.getEditModel();
		this.modalSelectOrganizations.selectOrgs(model).then(this.selectSchools);
	};

	reset(){
		this.initAnnounce().then(() => {
			this.syncDate();
			this.initFileAttachments();
		});
	}

	deleteDatePaste(){}

	save(){

		this.announceForm.$displayErrors = true;

		if (!this.announceForm.$valid) {
			return;
		}

		if (this.data.announcement.recipientGroup.length === 0) {
			this.$dialogs.message(this.language.Generic.Announcement.kSelectRecipient);
			return;
		}

		if (!this.selected.selectedIds || this.selected.selectedIds.length === 0) {
			this.$dialogs.message(this.language.Generic.Announcement.kSelectEducOrganizations);
			return;
		}

		if (!dateUtils.str2date(this.data.deleteDateStr)) {
			this.$dialogs.error(this.language.Generic.Announcement.kErrorBadDeletingDate);
			return;
		}


		if (this.data.announcement.description.length > this.descriptionMaxSize) {
			const errorMessage = this.language.Generic.Announcement.kAnnouncementMaxLengthMessage.replace("{0}", this.descriptionMaxSize);
			this.$dialogs.error(errorMessage);
			return;
		}

		const deleteDate = dateUtils.str2date(this.data.deleteDateStr);

		if (deleteDate < new Date() || deleteDate > new Date().addYears(1)) {
			this.$dialogs.error(this.language.Generic.Announcement.kErrorBadDeletingDate);
			return;
		}

		this.data.announcement.deleteDate = deleteDate;

		const mapFunc = (f) => ({ id: f.id });
		this.data.announcement.attachments = _.map(this.fa.data.files, mapFunc);
		this.data.announcement.schoolIds = this.selected.selectedIds;

		this.emAnnouncementsRepository.save(this.data.announcement).then(() => {
			this.changeTracker.clearDataChanges();
			if (this.state.createMode) {
				this.$alerts.success(this.language.Generic.Announcement.kAnnouncementIsSent);
			} else {
				this.$alerts.success(this.language.Generic.Announcement.kAnnouncementIsSaved);
			}

			this.$location.path(`/`);
		});
	};
}

class RolesManager {
	beautify(roles){
		//привожу имя роли к верхнему регистру
		for (let i = 0; i < roles.length; i++) {
			let role = roles[i];

			//для роли "Психолог / социальный педагог" - не меняем наименование (для единообразия с интерфейсом в школе)
			if (role.key === 'Psychologist') {
				continue;
			}

			role.name = this.roleToUpperCase(role.name);
		}
	}

	roleToUpperCase(roleStr) {
		let roleSplit = roleStr.split('/')

		let result = "";

		for (let i = 0; i < roleSplit.length; i++) {
			let role = roleSplit[i];

			result += ' / ' + this.firstLetterToUpper(role);
		}

		return result.slice(2).trim();
	}

	firstLetterToUpper(str) {
		str = str.trim();
		var result = str.charAt(0).toUpperCase() + str.slice(1);
		return result;
	}
}


