"use strict";

import { BaseRepository } from "approot/global/repository.js";

class EmAnnouncementsRepository extends BaseRepository {

	getAll() {
		return this.$http.get("/webapi/em/announcements")
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	getEdit(id) {
		return this.$http.get("/webapi/announcements/edit", { params: { id } })
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	getSchoolRoles() {
		return this.$http.get("/webapi/refs/schoolroles", { params: { language: appContext.language } })
			.then((response) => {
				return response.data;
			})
			.catch((err)=>{
				console.error(err);
				this.handleError(err);
			});
	}

	getSchoolsIds(id) {
		return this.$http.get("/webapi/announcements/schoolsIds", { params: { id } })
			.then(this.handleResponse, this.handleError);
	}

	delete(id) {
		var processing = $.show.processing();
		return this.$http.delete("/webapi/announcements", { params: { id } }).catch(this.handleError)
			.then(() => processing.close());
	}

	save(editAnnounce) {

		var processing = $.show.processing();
		return this.$http.post("/webapi/em/announcements", editAnnounce).catch(this.handleError)
			.then(() => processing.close());
	}


}

angular
	.module("irtech.netcity.em.announcements")
	.factory("emAnnouncementsRepository", ($http, $dialogs, $alerts) => new EmAnnouncementsRepository($http, $dialogs, $alerts))
	;


