import Selectable from "approot/global/selectable";

export class AnnouncementsCtrl {
	
	/*@ngInject*/
	constructor(pageContext, $location, $appLoader, $dialogs, $alerts, language, emAnnouncementsRepository, modalSelectOrganizations) {
		this.language = language;
		this.location = $location;
		this.$appLoader = $appLoader;

		this.emAnnouncementsRepository = emAnnouncementsRepository;
		this.modalSelectOrganizations = modalSelectOrganizations;
		this.$dialogs = $dialogs;
		this.$alerts = $alerts;

		this.selection = new Selectable();

		pageContext.parent = null;
		pageContext.title = this.language.Generic.Announcement.kTitleViewAnn;

		this.load();
	}

	load() {
		this.emAnnouncementsRepository.getAll()
			.then((announcements) => {
				announcements = announcements.sort(new AnnouncementComparer().compare);

				this.$appLoader.hide();
				this.announcements = announcements;
			});
	}

	add() {
		this.location.url("/announcements/add");
	}

	edit(announce){
		this.location.url(`/announcements/${announce.id}/edit`);
	}

	showOrgs(announcementId) {
		this.emAnnouncementsRepository.getSchoolsIds(announcementId)
			.then(schoolsIds => { this.modalSelectOrganizations.showOrgs({ selected: schoolsIds }); });
	}

	delete(announce){
		this.$dialogs.confirmDelete(this.language.Generic.Announcement.kAreYouReallySureToDelete)
			.then(() => {
				this.emAnnouncementsRepository.delete(announce.id).then(() => {
					this.$alerts.success(this.language.Generic.Announcement.kAttention1);
					this.selection.selected = [];
					this.load();
				});
			});
	};

};

class AnnouncementComparer{
	compare(ann1, ann2) {
		//сортирую объявления по дате публикации
		if (ann1.postDate > ann2.postDate) {
			return -1;
		} else if (ann1.postDate < ann2.postDate) {
			return 1;
		} else {
			return 0;
		}
	}
}


