const module = angular.module("irtech.netcity.em.announcements",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components", 'ui.tinymce'
	]);

tinymce.init({
	selector: 'textarea',
	language: 'ru',
});

require("./repository.js");
require("./index/announcementsCtrl.js");
require("./edit/editAnnouncementCtrl");
require('angular-ui-tinymce');

import { AnnouncementsCtrl } from "approot/em/announcements/index/announcementsCtrl.js"
import { EditAnnouncementCtrl } from "approot/em/announcements/edit/editAnnouncementCtrl.js";

module
	.controller("EditAnnouncementCtrl", EditAnnouncementCtrl)
	.controller("AnnouncementsCtrl", AnnouncementsCtrl)
	.config(($routeProvider, $locationProvider) => {

		$routeProvider
			.when("/announcements", {
				templateUrl: "/static/dist/app/em/announcements/index/template.html",
				controller: "AnnouncementsCtrl as ctrl"
			})
			.when("/announcements/add", {
				templateUrl: "/static/dist/app/em/announcements/edit/template.html",
				controller: "EditAnnouncementCtrl as ctrl"
			})
			.when("/announcements/:announcementId/edit", {
				templateUrl: "/static/dist/app/em/announcements/edit/template.html",
				controller: "EditAnnouncementCtrl as ctrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/em/announcements/index/template.html",
				controller: "AnnouncementsCtrl as ctrl",
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


